// Parse input parameters
const body = $input.first().json.body || {};

// Generate run_id if not provided
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const ts = now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes()) + pad(now.getSeconds());
const rnd = Math.random().toString(16).slice(2, 6);
const defaultRunId = `RUN-${ts}-${rnd}`;

const params = {
  run_id: body.run_id || defaultRunId,
  task_id: body.task_id || '',
  title: body.title || '',
  task_pack_path: body.task_pack_path || '',
  role: body.role || 'L3_engineer',
  task_type: body.task_type || 'code',
  complexity: body.complexity || 'normal',
  model_override: body.model_override || 'auto',
  resume_from_stage: Number(body.resume_from_stage || 0),
  project_root: body.project_root || '/home/shash/work/Footnote',
  started_at: now.toISOString(),
  raw_body: body
};

if (!params.task_id && !params.task_pack_path) {
  throw new Error('Either task_id or task_pack_path is required');
}

if (!params.task_id) {
  // Extract task_id from task_pack_path filename
  const match = params.task_pack_path.match(/\/(T-[^/]+)\.md$/);
  params.task_id = match ? match[1] : 'T-AUTO';
}

return { json: params };

// Write intake log
const params = $input.first().json;
const intakePath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/00_intake.json`;
const statusPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/status.json`;

const intake = {
  task_id: params.task_id,
  title: params.title,
  role: params.role,
  task_type: params.task_type,
  complexity: params.complexity,
  model_override: params.model_override,
  resume_from_stage: params.resume_from_stage,
  run_id: params.run_id,
  project_root: params.project_root,
  received_at: params.started_at,
  raw_body: params.raw_body
};

const status = {
  run_id: params.run_id,
  task_id: params.task_id,
  stage: 0,
  ok: false,
  started_at: params.started_at,
  updated_at: new Date().toISOString()
};

return {
  json: {
    ...params,
    intake_path: intakePath,
    status_path: statusPath,
    intake_content: JSON.stringify(intake, null, 2),
    status_content: JSON.stringify(status, null, 2)
  }
};

// Check git status result
const params = $('Parse Params').first().json;
const gitResult = $input.first().json;
const stdout = gitResult.stdout || '';
const exitCode = gitResult.exitCode || 0;

const isDirty = stdout.trim().length > 0;

if (isDirty || exitCode !== 0) {
  return {
    json: {
      ...params,
      preflight_ok: false,
      preflight_reason: isDirty ? 'repo_dirty' : 'git_status_failed',
      preflight_detail: stdout.trim().slice(0, 500)
    }
  };
}

return {
  json: {
    ...params,
    preflight_ok: true,
    preflight_reason: 'clean'
  }
};

// Write preflight log and update status
const params = $('Parse Params').first().json;
const pullResult = $input.first().json;
const preflightPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/01_preflight.json`;
const statusPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/status.json`;

const preflight = {
  ok: true,
  git_status: 'clean',
  git_pull: {
    exitCode: pullResult.exitCode,
    stdout: (pullResult.stdout || '').slice(0, 1000)
  },
  completed_at: new Date().toISOString()
};

const status = {
  run_id: params.run_id,
  task_id: params.task_id,
  stage: 1,
  stage_name: 'preflight',
  ok: true,
  updated_at: new Date().toISOString()
};

return {
  json: {
    ...params,
    preflight_path: preflightPath,
    preflight_content: JSON.stringify(preflight, null, 2),
    status_path: statusPath,
    status_content: JSON.stringify(status, null, 2)
  }
};

// Generate a minimal TaskPack
const params = $('Parse Params').first().json;
const now = new Date();
const ts = now.toISOString().replace(/[-:]/g, '').slice(0, 15);

const taskId = params.task_id || `T-${ts}_auto`;
const title = params.title || 'Auto Generated TaskPack';
const fileName = `${taskId}_auto.md`.replace(/[^a-zA-Z0-9._-]/g, '_');
const relPath = `design/ai-native/03_taskpacks/${fileName}`;

const content = `---
task_id: ${taskId}
title: "${title.replace(/"/g, '\\"')}"
task_type: ${params.task_type}
complexity: ${params.complexity}
model_override: ${params.model_override}
execution_runtime: wsl
---

# TASK-PACK: ${taskId}

## 1. Outcome（可观察结果）
${params.title || '-'}

## 2. Allowed Inputs（允许引用的输入）
- [\`dir\`] \`./\`

## 3. Deliverables（必须交付物）
- [\`file\`] \`design/ai-native/03_taskpacks/...\` (as needed)

## 4. Constraints（硬约束 / 禁止事项）
- 不得修改冻结目录：\`design/ai-native/00_charter/**\`、\`design/ai-native/01_bibles/**\`

## 5. Acceptance Checklist（验收清单）
- [ ] 交付物落盘
`;

return {
  json: {
    task_pack_path: relPath,
    task_pack_content: content,
    task_pack_generated: true
  }
};

// Merge TaskPack info
const params = $('Parse Params').first().json;
let taskPackPath = '';
let taskPackContent = '';

// Check which branch we came from
try {
  const readResult = $('Read TaskPack').first();
  if (readResult && readResult.json) {
    taskPackPath = params.task_pack_path;
    taskPackContent = readResult.json.stdout || '';
  }
} catch (e) {
  // Not from read branch
}

try {
  const writeResult = $('Write TaskPack').first();
  if (writeResult && writeResult.json) {
    const genResult = $('Generate TaskPack').first();
    taskPackPath = genResult.json.task_pack_path;
    taskPackContent = genResult.json.task_pack_content;
  }
} catch (e) {
  // Not from write branch
}

if (!taskPackPath) {
  taskPackPath = params.task_pack_path;
  taskPackContent = $input.first().json.stdout || '';
}

return {
  json: {
    ...params,
    task_pack_path: taskPackPath,
    task_pack_content: taskPackContent
  }
};

// Build cursor prompt
const params = $input.first().json;
const role = params.role;
const taskPackText = params.task_pack_content;

const prompt = `# Task Execution Instructions

## Current Role: ${role}

## Task Pack:
${taskPackText}

## Execution Rules:
1. Only read files listed in Allowed Inputs
2. Only write to paths listed in Deliverables
3. Follow all constraints strictly
4. Output a receipt in this format:

\`\`\`
【完成内容】
- ...

【输出文件】
- ...

【自检】
- [ ] ...

【风险与未完成】
- (如有)
\`\`\`
`;

const promptPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/_prompt.md`;

return {
  json: {
    ...params,
    prompt_path: promptPath,
    prompt_content: prompt
  }
};

// Check cursor execution result
const params = $('Parse Params').first().json;
const execResult = $input.first().json;
const exitCode = execResult.exitCode || 0;
const stdout = execResult.stdout || '';
const stderr = execResult.stderr || '';

const executePath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/04_execute.json`;
const statusPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/status.json`;

const executeLog = {
  ok: exitCode === 0,
  exit_code: exitCode,
  stdout: stdout.slice(0, 5000),
  stderr: stderr.slice(0, 2000),
  completed_at: new Date().toISOString()
};

const status = {
  run_id: params.run_id,
  task_id: params.task_id,
  stage: 4,
  stage_name: 'execute',
  ok: exitCode === 0,
  error: exitCode !== 0 ? 'cursor_agent_failed' : null,
  updated_at: new Date().toISOString()
};

return {
  json: {
    ...params,
    execute_ok: exitCode === 0,
    execute_exit_code: exitCode,
    execute_stdout: stdout,
    execute_path: executePath,
    execute_content: JSON.stringify(executeLog, null, 2),
    status_path: statusPath,
    status_content: JSON.stringify(status, null, 2)
  }
};

// Check validate result
const params = $('Parse Params').first().json;
const validateResult = $input.first().json;
const exitCode = validateResult.exitCode || 0;
const stdout = validateResult.stdout || '';

const validatePath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/05_validate.json`;
const statusPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/status.json`;

const validateLog = {
  ok: exitCode === 0,
  exit_code: exitCode,
  stdout: stdout.slice(0, 3000),
  completed_at: new Date().toISOString()
};

const status = {
  run_id: params.run_id,
  task_id: params.task_id,
  stage: 5,
  stage_name: 'validate',
  ok: exitCode === 0,
  error: exitCode !== 0 ? 'validate_failed' : null,
  updated_at: new Date().toISOString()
};

return {
  json: {
    ...params,
    validate_ok: exitCode === 0,
    validate_path: validatePath,
    validate_content: JSON.stringify(validateLog, null, 2),
    status_path: statusPath,
    status_content: JSON.stringify(status, null, 2)
  }
};

// Check if there are changes to commit
const params = $('Parse Params').first().json;
const addResult = $input.first().json;
const changedFiles = (addResult.stdout || '').split('\n').filter(f => f.trim()).length;

return {
  json: {
    ...params,
    has_changes: changedFiles > 0,
    changed_files: changedFiles
  }
};

// Prepare git log
const params = $('Parse Params').first().json;
const hasChanges = $('Check Changes').first().json.has_changes;

let commitResult = { exitCode: 0, stdout: 'no_changes' };
let pushResult = { exitCode: 0, stdout: 'no_changes' };

try {
  commitResult = $('Git Commit').first().json;
} catch (e) {}

try {
  pushResult = $('Git Push').first().json;
} catch (e) {}

const gitPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/06_git.json`;
const statusPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/status.json`;

const gitOk = !hasChanges || (commitResult.exitCode === 0 && pushResult.exitCode === 0);

const gitLog = {
  ok: gitOk,
  has_changes: hasChanges,
  commit: hasChanges ? { exitCode: commitResult.exitCode, stdout: (commitResult.stdout || '').slice(0, 1000) } : null,
  push: hasChanges ? { exitCode: pushResult.exitCode, stdout: (pushResult.stdout || '').slice(0, 1000) } : null,
  completed_at: new Date().toISOString()
};

const status = {
  run_id: params.run_id,
  task_id: params.task_id,
  stage: 6,
  stage_name: 'git',
  ok: gitOk,
  error: !gitOk ? 'git_failed' : null,
  updated_at: new Date().toISOString()
};

return {
  json: {
    ...params,
    git_ok: gitOk,
    git_path: gitPath,
    git_content: JSON.stringify(gitLog, null, 2),
    status_path: statusPath,
    status_content: JSON.stringify(status, null, 2)
  }
};

// Prepare success notification
const params = $('Parse Params').first().json;

return {
  json: {
    ...params,
    notify_ok: true,
    notify_stage: 99,
    notify_message: `task_id=${params.task_id}\nrun_id=${params.run_id}\nstage=99\nok=true\ntitle=${params.title || ''}\nlogs=workflows/project/logs/automation_runs/${params.run_id}`
  }
};

// Prepare failure notification from different stages
const params = $('Parse Params').first().json;

// Determine which stage failed
let failedStage = 0;
let failedReason = 'unknown';

try {
  const preflightCheck = $('Check Git Status').first();
  if (preflightCheck && !preflightCheck.json.preflight_ok) {
    failedStage = 1;
    failedReason = preflightCheck.json.preflight_reason || 'preflight_failed';
  }
} catch (e) {}

try {
  const executeCheck = $('Check Execute').first();
  if (executeCheck && !executeCheck.json.execute_ok) {
    failedStage = 4;
    failedReason = 'execute_failed';
  }
} catch (e) {}

try {
  const validateCheck = $('Check Validate').first();
  if (validateCheck && !validateCheck.json.validate_ok) {
    failedStage = 5;
    failedReason = 'validate_failed';
  }
} catch (e) {}

try {
  const gitLog = $('Prepare Git Log').first();
  if (gitLog && !gitLog.json.git_ok) {
    failedStage = 6;
    failedReason = 'git_failed';
  }
} catch (e) {}

return {
  json: {
    ...params,
    notify_ok: false,
    notify_stage: failedStage,
    notify_reason: failedReason,
    notify_message: `task_id=${params.task_id}\nrun_id=${params.run_id}\nstage=${failedStage}\nok=false\nreason=${failedReason}\nlogs=workflows/project/logs/automation_runs/${params.run_id}`
  }
};

// Write final status and notify log
const params = $('Parse Params').first().json;
const notifyOk = $json.notify_ok !== false;
const notifyStage = $json.notify_stage || 99;

const notifyPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/07_notify.json`;
const statusPath = `${params.project_root}/workflows/project/logs/automation_runs/${params.run_id}/status.json`;

const notifyLog = {
  ok: notifyOk,
  stage: notifyStage,
  message: $json.notify_message,
  completed_at: new Date().toISOString()
};

const status = {
  run_id: params.run_id,
  task_id: params.task_id,
  stage: notifyOk ? 99 : notifyStage,
  stage_name: notifyOk ? 'done' : 'failed',
  ok: notifyOk,
  error: notifyOk ? null : ($json.notify_reason || 'failed'),
  completed_at: new Date().toISOString()
};

return {
  json: {
    run_id: params.run_id,
    task_id: params.task_id,
    ok: notifyOk,
    stage: status.stage,
    notify_path: notifyPath,
    notify_content: JSON.stringify(notifyLog, null, 2),
    status_path: statusPath,
    status_content: JSON.stringify(status, null, 2)
  }
};
